import json,re
from pathlib import Path
recipes=[]

def add(title,group,prep,cook,serves,ingredients,method,description,tip=''):
    slug='at-home-'+re.sub('[^a-z0-9]+','-',title.lower()).strip('-')
    recipes.append(dict(slug=slug,title=title,place='At home recipes · '+group,story=description,ingredients=ingredients.split('|'),method=method,image='/images/at-home/'+slug+'.webp',category='Dessert' if 'Chocolate pots' in title else 'Main',number=str(100+len(recipes)+1),prepTime=f'PT{prep}M',cookTime=f'PT{cook}M',serves=str(serves),datePublished='2026-11-12',faqs=[],atHomeCategory=group,editorialLabel='At home recipes',notes=[dict(title='Make it your own',text=tip or 'Taste before serving and adjust the seasoning a little at a time. Check ingredient labels for allergens and dietary suitability.'),dict(title='A note from the OPR kitchen',text='An OPR editorial recipe for everyday home cooking. Timings are a guide and depend on your equipment; follow the method and check food is fully cooked. This recipe has not been independently kitchen-tested.')]))

Q='15 minute'
# Pasta and gnocchi: the sauce cooks while the pasta boils.
def quick_pasta(title,base,extras,sauce,finish,desc):
    add(title,Q,5,10,2,base+'|'+extras,["Put the kettle on while you prepare the ingredients. Bring a large pan of water to the boil. Cook the pasta or gnocchi for the time on the packet; choose a variety that cooks in no more than 10 minutes. Reserve a mug of cooking water before draining.",sauce,finish+' Loosen with a splash of the reserved cooking water, divide between two bowls and serve immediately.'],desc,'Have the ingredients measured before you begin. Use a quick-cooking pasta so the meal fits the 15-minute window.')
quick_pasta('Lemon and pea pasta','180 g quick-cooking pasta','120 g frozen peas|1 lemon, zest and 1 tbsp juice|1 tbsp olive oil|30 g vegetarian hard cheese, grated|Black pepper','Add the peas to the pasta for the last 3 minutes. In a large bowl, mix the olive oil, lemon zest, lemon juice and black pepper.','Toss the hot pasta and peas through the lemon dressing and grated cheese.','A bright, simple pasta with sweet peas, lemon and a little cheese.')
quick_pasta('Tomato and basil spaghetti','180 g spaghetti with a 10-minute cooking time','250 g cherry tomatoes, halved|1 garlic clove, finely chopped|1 tbsp olive oil|10 basil leaves, torn|Salt and black pepper','Warm the oil in a frying pan. Cook the garlic for 30 seconds, add the tomatoes and simmer for 7–8 minutes until softened. Season lightly.','Fold the spaghetti through the tomato sauce, then add the basil.','A short ingredient list and fresh basil turn cherry tomatoes into a quick supper.')
quick_pasta('Creamy mushroom tagliatelle','180 g quick-cooking tagliatelle','200 g mushrooms, sliced|1 garlic clove, chopped|1 tbsp olive oil|80 g soft cream cheese|1 tbsp chopped parsley|Black pepper','Fry the mushrooms in the olive oil for 6–7 minutes. Add the garlic for 1 minute. Stir in the cream cheese and 3 tbsp pasta water until smooth.','Toss the tagliatelle through the sauce and finish with parsley and black pepper.','Mushrooms and soft cheese make a comforting sauce without a long simmer.')
quick_pasta('Garlic prawn linguine','180 g quick-cooking linguine','180 g cooked peeled prawns, thawed if frozen|2 garlic cloves, sliced|1 tbsp olive oil|1 tbsp lemon juice|1 tbsp parsley, chopped|Black pepper','Warm the olive oil and gently cook the garlic for 1 minute. Add the cooked prawns and 2 tbsp pasta water; heat gently until the prawns are piping hot throughout.','Toss with the linguine, lemon juice, parsley and pepper.','Use cooked prawns for a fast garlic and lemon pasta.')
quick_pasta('Pesto gnocchi','400 g fresh gnocchi','3 tbsp basil pesto|150 g cherry tomatoes, halved|60 g baby spinach|1 tbsp olive oil|20 g vegetarian hard cheese, grated','Warm the oil in a large pan. Soften the tomatoes for 4 minutes, then add the spinach and let it wilt. Stir in the pesto and 2 tbsp cooking water.','Add the drained gnocchi and fold gently, then scatter over the cheese.','Soft gnocchi, pesto and a handful of spinach for a quick pan supper.')
quick_pasta('Broccoli and cheese pasta','180 g quick-cooking pasta','180 g broccoli, in small florets|80 g cream cheese|40 g cheddar, grated|1 tsp Dijon mustard|Black pepper','Add the broccoli to the pasta water for the last 5 minutes. Mix cream cheese, cheddar, mustard and 3 tbsp hot cooking water in a warm serving bowl.','Toss in the hot pasta and tender broccoli, then season with pepper.','Broccoli and two cheeses make a speedy bowl that is easy to share.')
quick_pasta('Ricotta and spinach gnocchi','400 g fresh gnocchi','150 g ricotta|100 g baby spinach|1 garlic clove, chopped|1 tbsp olive oil|1 tbsp lemon juice|Black pepper','Warm the oil in a frying pan and soften the garlic for 30 seconds. Add the spinach and 2 tbsp water; stir until wilted. Fold in the ricotta and a little gnocchi water.','Add the cooked gnocchi, lemon juice and black pepper and heat gently until hot.','A soft ricotta sauce and fresh spinach keep this gnocchi gentle and simple.')

def assemble(title,ings,method,desc,hot=False):add(title,Q,8 if hot else 15,7 if hot else 0,2,ings,method,desc)
assemble('Tuna and sweetcorn wraps','145 g drained tinned tuna|100 g drained tinned sweetcorn|2 tbsp mayonnaise|1 tbsp lemon juice|4 small tortilla wraps|60 g shredded lettuce|Black pepper',["Flake the tuna into a bowl. Mix with sweetcorn, mayonnaise, lemon juice and black pepper.","Lay out the wraps and divide the lettuce and tuna mixture between them.","Fold in the ends, roll tightly and cut in half. Serve straight away, or refrigerate promptly if packing for later."],'A straightforward lunch from cupboard tuna, sweetcorn and crisp lettuce.')
assemble('Chickpea and cucumber pittas','240 g drained tinned chickpeas|100 g cucumber, diced|100 g tomatoes, diced|2 tbsp plain yoghurt|1 tbsp lemon juice|1 tbsp olive oil|4 small pitta breads|Salt and pepper',["Lightly mash the chickpeas with a fork. Stir in cucumber, tomato, yoghurt, lemon and olive oil. Season to taste.","Warm the pittas following the packet instructions and open carefully.","Fill with the chickpea salad and serve. Keep the filling chilled if not eating immediately."],'Chickpeas and a lemon yoghurt dressing fill warm pittas for an easy lunch.')
assemble('Spinach and feta omelette','4 eggs|60 g spinach|60 g feta, crumbled|1 tsp olive oil|2 slices bread|Black pepper',["Beat the eggs with black pepper. Warm the oil in a non-stick pan and wilt the spinach for 1 minute.","Pour in the eggs. Cook over medium-low heat, lifting the edges so uncooked egg runs underneath. Add the feta.","Fold carefully and cook until the centre is fully set with no runny egg. Toast the bread while the omelette cooks and divide between two plates."],'A quick omelette with spinach, salty feta and toast.',True)
assemble('Cheese and tomato toasties','4 slices bread|80 g cheddar, grated|1 tomato, thinly sliced|10 g butter|1 tsp mustard|Black pepper',["Butter the outside of each bread slice. Spread mustard inside and fill with cheese, tomato and pepper.","Cook the sandwiches in a dry non-stick frying pan over medium-low heat for 3–4 minutes per side, pressing gently, until the cheese has melted and the bread is golden.","Rest for a minute before slicing; the tomato filling will be hot."],'Crisp pan-toasted sandwiches with melted cheese and juicy tomato.',True)
assemble('Hummus and roasted pepper flatbreads','2 ready-made flatbreads|120 g hummus|120 g drained roasted peppers from a jar, sliced|80 g cucumber, diced|30 g rocket|1 tbsp lemon juice|1 tbsp olive oil',["Warm the flatbreads following the packet instructions.","Spread with hummus, then add the peppers, cucumber and rocket.","Mix lemon juice and olive oil, spoon over lightly and serve folded or sliced."],'Jarred roasted peppers and hummus make an easy flatbread lunch.')
assemble('Smoked mackerel salad','200 g ready-to-eat smoked mackerel, skin removed|120 g mixed salad leaves|150 g ready-cooked beetroot, diced|100 g cucumber, sliced|1 tbsp olive oil|1 tbsp lemon juice|1 tsp Dijon mustard',["Check the mackerel carefully for bones and break it into pieces.","Mix the salad leaves, beetroot and cucumber on two plates. Whisk oil, lemon juice and mustard together.","Add the mackerel and spoon over the dressing just before serving. Follow the fish packet storage instructions."],'Smoked mackerel, beetroot and a sharp dressing make a substantial salad.')
assemble('Caprese toast','4 slices sourdough bread|150 g mozzarella, drained|2 ripe tomatoes, sliced|10 basil leaves|1 tbsp olive oil|1 tsp balsamic vinegar|Black pepper',["Toast the bread. Tear the mozzarella and arrange with the tomatoes over the warm toast.","Scatter over basil, drizzle with olive oil and balsamic vinegar and add black pepper.","Serve immediately while the bread is still crisp."],'Tomato, mozzarella and basil on crisp toast for a relaxed lunch.')
assemble('Chicken pesto wraps','200 g ready-cooked chicken, shredded|4 small wraps|2 tbsp pesto|2 tbsp plain yoghurt|60 g lettuce|100 g cherry tomatoes, quartered',["Use chilled ready-cooked chicken within its use-by date. Mix the pesto and yoghurt in a bowl.","Lay lettuce and tomatoes over the wraps, then add the chicken and pesto yoghurt.","Roll up and serve cold, or refrigerate promptly. Do not leave the filled wraps at room temperature."],'Ready-cooked chicken and pesto yoghurt make a useful no-cook wrap.')
assemble('Avocado and scrambled eggs on toast','4 eggs|1 ripe avocado|4 slices bread|10 g butter|1 tbsp lemon juice|Black pepper',["Mash avocado with lemon juice. Toast the bread while you beat the eggs.","Melt butter in a non-stick pan over low-medium heat. Add eggs and stir gently until fully set, with no runny egg.","Spread avocado on toast, add the scrambled eggs and black pepper and serve straight away."],'Eggs and avocado turn toast into a quick, filling meal.',True)
assemble('Sardines and lemon on toast','2 tins sardines in olive oil, about 180 g drained|4 slices bread|1 tbsp lemon juice|1 tbsp chopped parsley|100 g cherry tomatoes, quartered|Black pepper',["Toast the bread and divide between two plates.","Gently flake the sardines and mix with lemon juice, parsley and pepper.","Spoon onto the toast, add the tomatoes and serve immediately."],'A cupboard-friendly lunch with sardines, lemon and parsley.')
assemble('Mushrooms and eggs on toast','200 g mushrooms, sliced|4 eggs|4 slices bread|1 tbsp olive oil|1 tbsp chopped parsley|Black pepper',["Heat the oil and fry the mushrooms for 5–6 minutes until softened. Push to one side of the pan.","Beat the eggs and pour into the clear side. Stir gently until completely set, then fold through the mushrooms.","Toast the bread, add the mushroom eggs, scatter over parsley and season with pepper."],'Mushrooms and fully set scrambled eggs for a quick hot meal.',True)

def couscous(title,extras,steps,desc):
 add(title,Q,5,10,2,'150 g couscous|180 ml boiling vegetable stock|'+extras,["Put the couscous in a heatproof bowl, pour over the boiling stock and cover for 5 minutes, or follow its packet instructions.",*steps,"Fluff the couscous with a fork, combine with the prepared topping and divide between two bowls."],desc,'Choose standard instant couscous, not giant couscous, for this timing.')
couscous('Spiced chickpea couscous','240 g drained tinned chickpeas|1 tsp cumin|1 tbsp olive oil|100 g grated carrot|1 tbsp lemon juice|1 tbsp parsley', ["Warm the oil in a pan, stir in cumin for 20 seconds, then add chickpeas and 2 tbsp water. Heat until piping hot.","Stir carrot, lemon juice and parsley into the hot chickpeas."],'Warm chickpeas and cumin give instant couscous plenty of flavour.')
couscous('Harissa carrot couscous','2 carrots, grated|240 g drained tinned chickpeas|1 tsp mild harissa|1 tbsp olive oil|1 tbsp lemon juice',["Heat oil in a pan and soften the grated carrot for 3 minutes. Add harissa, chickpeas and 2 tbsp water.","Stir until piping hot, then add lemon juice."],'Grated carrot and mild harissa make a colourful couscous bowl.')
couscous('Halloumi and lemon couscous','160 g halloumi, sliced|1 tsp olive oil|100 g cherry tomatoes, halved|80 g cucumber, diced|1 tbsp lemon juice',["Pat the halloumi dry. Warm the oil in a frying pan and cook the slices for 2 minutes per side until golden.","Mix tomatoes, cucumber and lemon juice. Add the cooked halloumi just before serving."],'Golden halloumi and a fresh tomato salad over fluffy couscous.')
couscous('Tuna and tomato couscous','145 g drained tinned tuna|150 g cherry tomatoes, quartered|60 g cucumber, diced|1 tbsp olive oil|1 tbsp lemon juice|Black pepper',["Flake the tuna. Mix with tomatoes, cucumber, olive oil, lemon juice and black pepper.","Check the couscous is tender before combining; eat immediately or chill promptly."],'A quick couscous lunch built around tuna, tomatoes and lemon.')

def noodles(title,extras,step,desc,cold=False):
 add(title,Q,5,10,2,'150 g quick-cooking noodles|'+extras,["Cook the noodles following the packet instructions, choosing a variety ready in 4 minutes or less. Drain"+(' and rinse briefly under cold water.' if cold else ', reserving a splash of cooking water.'),step,"Toss everything together thoroughly and divide between two bowls. Serve straight away."],desc,'Check sauces and noodles for wheat, soy, sesame and other allergens.')
noodles('Peanut noodles','2 tbsp smooth peanut butter|1 tbsp soy sauce|1 tbsp lime juice|1 tsp honey|80 g grated carrot|80 g shredded cabbage|2 tbsp hot water',"Whisk peanut butter, soy sauce, lime juice, honey and hot water until smooth. Fold the carrot and finely shredded cabbage through the drained noodles.",'A creamy peanut dressing coats quick noodles and crunchy vegetables.')
noodles('Miso mushroom noodles','200 g mushrooms, sliced|1 tbsp oil|1 tbsp white miso|1 tbsp soy sauce|80 g baby spinach|100 ml hot water',"Fry mushrooms in the oil for 5 minutes. Stir miso and soy sauce into the hot water, add to the pan with spinach and simmer for 2 minutes.",'Mushrooms, miso and spinach make a savoury noodle bowl.')
noodles('Chilled cucumber sesame noodles','150 g cucumber, cut into thin strips|1 tbsp tahini|1 tbsp soy sauce|1 tbsp rice vinegar|1 tsp sesame oil|2 tbsp water',"Whisk tahini, soy sauce, vinegar, sesame oil and water. Add cucumber strips to the cooled noodles.",'Cool cucumber and a sesame dressing for a light noodle supper.',True)
noodles('Sesame tofu stir-fry','200 g firm tofu, drained and cubed|150 g ready-cut stir-fry vegetables|1 tbsp oil|1 tbsp soy sauce|1 tsp sesame oil|1 tbsp sweet chilli sauce',"Fry tofu in the oil for 4 minutes. Add vegetables and stir-fry for 3–4 minutes, following the tofu packet cooking instructions. Stir through soy, sesame oil and sweet chilli sauce, heating until piping hot.",'Tofu and ready-cut vegetables keep a colourful stir-fry quick.')

def beans(title,base,extras,step,desc):add(title,Q,5,10,2,base+'|'+extras,[step,"Add the beans and 3 tbsp water. Simmer gently for 5–6 minutes, stirring, until piping hot throughout.","Taste, add the listed finishing ingredients and divide between two plates."],desc,'These timings require tinned or already-cooked beans; do not substitute raw dried beans.')
beans('Garlicky butter beans and tomatoes','480 g drained tinned butter beans','200 g cherry tomatoes, halved|2 garlic cloves, chopped|1 tbsp olive oil|1 tbsp chopped parsley|Black pepper',"Warm the oil and soften garlic for 30 seconds. Add tomatoes and cook for 3 minutes.",'Butter beans simmered briefly with garlic and sweet tomatoes.')
beans('Smoky beans on toast','480 g drained tinned mixed beans','200 g passata|1 tsp smoked paprika|1 tbsp olive oil|4 slices bread|Black pepper',"Warm the oil and stir in paprika for 20 seconds. Add passata and black pepper. Toast the bread while the beans simmer.",'A smoky tomato bean topping for warm toast.')
beans('Lemon white beans and spinach','480 g drained tinned cannellini beans','100 g spinach|1 garlic clove, chopped|1 tbsp olive oil|1 tbsp lemon juice|Black pepper',"Warm oil and garlic for 30 seconds. Add the spinach and stir until wilted. Reserve the lemon juice to add after heating.",'Lemon and spinach brighten a simple pan of white beans.')
beans('Spicy butter bean pittas','480 g drained tinned butter beans','150 g passata|1 tsp mild harissa|1 tbsp olive oil|4 small pitta breads|2 tbsp plain yoghurt',"Warm oil, harissa and passata in a pan. Warm the pittas following the packet instructions while the beans simmer. Serve the hot beans in the pittas with yoghurt.",'Warm butter beans in a gently spiced tomato sauce, tucked into pittas.')

def rice_bowl(title,extras,step,desc):add(title,Q,5,10,2,'250 g ready-cooked microwave rice|'+extras,["Heat the rice exactly as the packet directs. Use a fresh unopened pouch, not leftover rice.",step,"Divide the hot rice between two bowls and add the prepared topping. Eat immediately."],desc,'Ready-cooked pouch rice is essential to the 15-minute timing. Follow its storage and heating instructions.')
rice_bowl('Salmon rice bowls','170 g drained tinned salmon|100 g cucumber, diced|1 avocado, sliced|1 tbsp soy sauce|1 tbsp lemon juice|1 tsp sesame seeds',"Check salmon for bones and flake it. Arrange cucumber and avocado alongside, and mix soy sauce and lemon juice as a dressing. Scatter the sesame seeds over the finished bowls.",'A quick rice bowl with tinned salmon, avocado and crisp cucumber.')
rice_bowl('Prawn and mango rice bowls','180 g cooked peeled prawns, thawed|1 small mango, diced|100 g cucumber, diced|1 tbsp lime juice|1 tbsp olive oil|1 tbsp chopped coriander',"Use ready-to-eat cooked prawns within their use-by date. Mix prawns, mango, cucumber, lime, olive oil and coriander; keep chilled until the rice is ready.",'Sweet mango and ready-cooked prawns over freshly heated rice.')
add('Chilli egg fried rice',Q,5,10,2,'250 g ready-cooked microwave rice|3 eggs|100 g frozen peas|2 spring onions, sliced|1 tbsp oil|1 tbsp soy sauce|1 tsp mild chilli sauce',["Heat rice following its packet instructions. Use a fresh unopened pouch.","Heat oil in a wide pan. Beat the eggs, pour them in and stir until fully set.","Add peas and spring onions with 2 tbsp water. Stir-fry for 3–4 minutes until peas are piping hot.","Fold in the hot rice, soy and chilli sauce. Stir-fry until piping hot throughout and serve immediately."],'Freshly heated rice, eggs and peas make a useful fast supper.')
add('Black bean quesadillas',Q,5,10,2,'240 g drained tinned black beans|4 tortilla wraps|80 g grated cheddar|1 tsp cumin|2 tbsp tomato salsa|1 tsp oil',["Mash the beans with cumin and salsa. Divide between two tortillas and add the cheese. Cover with the remaining tortillas.","Brush a frying pan with oil. Cook one quesadilla at a time for 3–4 minutes each side over medium-low heat, until the cheese melts and filling is piping hot.","Rest briefly, cut into wedges and serve."],'Crisp tortillas with a warm black bean and cheese filling.')
add('Cinnamon French toast',Q,5,10,2,'4 thick slices bread|2 eggs|80 ml milk|1 tsp cinnamon|10 g butter|100 g plain yoghurt|100 g berries',["Whisk eggs, milk and cinnamon in a shallow bowl. Dip bread briefly on each side without soaking it until it breaks.","Melt butter in a non-stick pan over medium heat. Cook the bread for 3–4 minutes per side, in batches, until golden and the egg coating is fully cooked.","Serve with yoghurt and berries."],'A simple sweet brunch with cinnamon, yoghurt and fruit.')
add('Tomato and lentil soup',Q,5,10,2,'400 g tinned chopped tomatoes|240 g drained tinned green lentils|300 ml vegetable stock|1 small carrot, grated|1 tbsp olive oil|1 tsp dried oregano|Black pepper',["Warm oil in a saucepan and soften grated carrot for 2 minutes.","Add tomatoes, lentils, stock and oregano. Bring to the boil, then simmer for 8 minutes until piping hot throughout.","Season with black pepper. Mash lightly with a potato masher or leave chunky and serve."],'Tinned lentils make a comforting tomato soup possible in a short lunch break.')
add('Sweetcorn fritters',Q,5,10,2,'160 g drained tinned sweetcorn|1 egg|60 g self-raising flour|40 ml milk|2 spring onions, sliced|1 tbsp oil|2 tbsp plain yoghurt|Black pepper',["Whisk egg, flour and milk to make a thick batter. Stir in sweetcorn, spring onions and pepper.","Heat oil in a non-stick pan. Spoon in six small fritters and cook for 3–4 minutes each side over medium heat, until golden and fully set in the centre. Cook in batches if needed.","Serve hot with the yoghurt."],'Small pan-cooked sweetcorn fritters with a spoonful of yoghurt.')
add('Tortilla pizzas',Q,5,10,2,'2 large tortilla wraps|4 tbsp passata|100 g grated mozzarella|100 g cherry tomatoes, halved|1 tsp dried oregano|1 tsp olive oil',["Heat the oven to 220°C (200°C fan) and place a baking tray inside to warm. Assemble while it heats.","Lay tortillas on baking paper, spread with passata and add mozzarella, tomatoes and oregano. Drizzle with oil.","Slide onto the hot tray and bake for 7–9 minutes until the cheese is bubbling and the edges crisp. Check closely so the tortillas do not burn."],'Thin tortilla bases make a quick tomato and mozzarella pizza.','Use thin tortillas and a preheated oven; allow extra time if your oven heats slowly.')
assemble('Peanut cabbage slaw bowls','200 g finely shredded cabbage|100 g grated carrot|240 g drained tinned chickpeas|2 tbsp peanut butter|1 tbsp soy sauce|1 tbsp lime juice|3 tbsp water|2 small flatbreads',["Whisk peanut butter, soy sauce, lime and water into a smooth dressing.","Toss cabbage, carrot and chickpeas with the dressing.","Divide between bowls and serve with the flatbreads, warmed following their packet instructions if preferred."],'Crunchy cabbage and chickpeas with a creamy peanut dressing.')
add('Vegetable fajita wraps',Q,5,10,2,'2 bell peppers, thinly sliced|1 small onion, thinly sliced|240 g drained tinned black beans|1 tbsp oil|1 tsp smoked paprika|1 tsp cumin|4 small tortilla wraps|2 tbsp plain yoghurt',["Heat oil in a wide pan and fry thinly sliced peppers and onion for 6 minutes, stirring.","Add beans, paprika, cumin and 2 tbsp water. Cook for 3 minutes until beans are piping hot and vegetables tender.","Warm wraps according to the packet. Fill with the vegetables and beans, then spoon over yoghurt."],'A quick pan of peppers and beans, ready to tuck into warm wraps.')
assert len(recipes)==40,len(recipes)
F='Family'
safe='Check the thickest pieces of every meat or fish ingredient reach 75°C for at least 30 seconds with a clean food thermometer. Continue cooking if needed; time and colour alone are not reliable.'
def tray(title,ings,prepstep,bake,desc,tip=''):
 add(title,F,15,bake,4,ings,["Heat the oven to 200°C (180°C fan). Choose a large roasting tray so the ingredients sit in a single layer.",prepstep,f"Roast for about {bake} minutes, turning or stirring vegetables halfway through. Add a splash of water if the tray becomes dry.",safe,"Check the vegetables are tender all the way through. Rest for 5 minutes and divide between four plates."],desc,tip)
tray('Lemon chicken traybake','8 small boneless chicken thighs|700 g potatoes, cut into 2 cm pieces|3 carrots, sliced|1 onion, cut into wedges|1 lemon, juice and wedges|2 tbsp olive oil|1 tsp dried oregano|Salt and pepper',"Toss chicken, potatoes, carrots and onion with oil, oregano, half the lemon juice and seasoning. Place lemon wedges around the tray; reserve remaining juice for serving.",45,'Lemon and oregano bring a simple chicken and potato traybake together.')
tray('Salmon and potato bake','4 salmon fillets, about 140 g each|700 g potatoes, thinly sliced|200 g green beans|1 lemon|2 tbsp olive oil|1 tsp dried dill|Salt and pepper',"Toss potatoes with half the oil and seasoning. Roast them alone for 25 minutes. Then add salmon and green beans, drizzle with remaining oil and lemon juice, and scatter with dill. Cook for a further 15–20 minutes; the total oven time is about 45 minutes.",45,'Thinly sliced potatoes cook beneath salmon and green beans.','Add the salmon after the potatoes have had their head start. If potatoes are still firm, keep cooking them after removing the cooked fish.')
# This recipe has staged timing rather than repeating the total roast instruction.
recipes[-1]['method'][2]='After adding the salmon and beans, roast for 15–20 minutes. Total oven time is around 45 minutes. Check the fish temperature rather than relying on the clock.'
tray('Sausage and pepper traybake','8 pork sausages|3 bell peppers, sliced|2 red onions, cut into wedges|600 g potatoes, in 2 cm pieces|2 tbsp olive oil|1 tsp dried thyme|Black pepper',"Toss peppers, onion and potatoes with oil, thyme and pepper. Arrange sausages among the vegetables.",45,'A generous tray of sausages, potatoes and sweet roasted peppers.')
tray('Pork and apple traybake','4 boneless pork chops|3 apples, cored and cut into wedges|2 onions, in wedges|600 g potatoes, thinly sliced|2 tbsp olive oil|1 tsp dried sage|Salt and pepper',"Toss potatoes, onions and apples with oil and sage. Roast for 20 minutes first, then place pork chops over the vegetables and season. Roast for a further 20–25 minutes.",45,'Pork, apples and sage share one tray for a cosy family meal.')
recipes[-1]['method'][2]='Once the pork is added, roast for a further 20–25 minutes, turning the chops halfway through. Total oven time is around 45 minutes.'
tray('Chicken fajita traybake','600 g boneless chicken breast, in strips|3 bell peppers, sliced|2 onions, sliced|2 tbsp olive oil|2 tsp smoked paprika|1 tsp cumin|8 small tortilla wraps|120 g plain yoghurt|1 lime',"Toss chicken, peppers and onions with oil, paprika and cumin. Spread on the tray. Warm the wraps according to the packet when the chicken is almost ready; mix yoghurt with lime juice to serve.",30,'An oven-cooked fajita filling, ready to bring to the table with wraps and yoghurt.')

# Pots and sauces with explicit heating and doneness instructions.
def pot(title,ings,first,second,mins,desc,meat=False,finish='Divide between four bowls and serve hot.'):
 add(title,F,15,mins,4,ings,[first,second,f"Bring to a gentle simmer and cook for about {mins} minutes, stirring occasionally and adding water if it becomes too thick. Check all vegetables and pulses are completely tender.",*([safe] if meat else []),finish],desc)
pot('Weeknight spaghetti bolognese','500 g beef mince|1 onion, finely chopped|2 carrots, grated|2 garlic cloves, chopped|1 tbsp olive oil|400 g tinned chopped tomatoes|2 tbsp tomato purée|150 ml beef stock|1 tsp dried oregano|300 g spaghetti|Salt and pepper',"Warm oil in a large pan. Soften onion and carrot for 6 minutes, then add garlic and mince. Cook, breaking up the mince, until well browned.","Stir in tomato purée, tomatoes, stock and oregano. Season lightly. Cook the spaghetti in a separate pan following its packet instructions while the sauce simmers.",30,'A straightforward beef and tomato sauce for the family pasta bowl.',True,'Drain the spaghetti, divide between four bowls and spoon the hot sauce over it.')
pot('Three-bean vegetable chilli','3 tins mixed beans, about 720 g drained|1 onion, chopped|2 bell peppers, diced|1 tbsp oil|400 g tinned chopped tomatoes|2 tbsp tomato purée|2 tsp cumin|1 tsp smoked paprika|1 tsp mild chilli powder|250 ml vegetable stock|250 g dry rice|Salt',"Warm oil and soften onion and peppers for 7 minutes. Stir in cumin, paprika, chilli and tomato purée for 30 seconds.","Add tomatoes, drained tinned beans and stock. Cook the rice separately according to its packet instructions.",25,'Three types of beans make a colourful chilli for everyday family dinners.',False,'Taste and add salt if needed. Serve the piping-hot chilli over freshly cooked rice.')
pot('Chickpea and spinach curry','720 g drained tinned chickpeas|1 onion, chopped|2 garlic cloves, chopped|1 tbsp grated ginger|1 tbsp oil|2 tsp curry powder|400 g tinned chopped tomatoes|200 ml coconut milk|150 g spinach|250 g dry rice|Salt',"Warm oil and soften onion for 6 minutes. Add garlic and ginger for 1 minute, then stir in curry powder.","Add tomatoes, coconut milk and chickpeas. Cook the rice separately while the curry simmers; add spinach for the final 3 minutes.",25,'A gentle chickpea curry with coconut milk and a handful of spinach.',False,'Taste and add salt as needed. Serve the curry piping hot with the freshly cooked rice.')
pot('Red lentil dal','250 g dry red lentils, rinsed|1 onion, chopped|2 garlic cloves, chopped|1 tbsp grated ginger|1 tbsp oil|1 tsp turmeric|2 tsp cumin|400 g tinned chopped tomatoes|900 ml water|250 g dry rice|1 tbsp lemon juice|Salt',"Warm oil and soften onion for 6 minutes. Add garlic, ginger, cumin and turmeric for 1 minute.","Add lentils, tomatoes and water. Bring to a boil before reducing the heat. Cook the rice separately following the packet.",30,'A soft red lentil dal, made with tomatoes and warming spices.',False,'Make sure the lentils are completely tender. Stir in lemon juice, season with salt and serve with freshly cooked rice.')
pot('Beef and tomato rice pot','500 g beef mince|1 onion, chopped|2 bell peppers, diced|1 tbsp oil|300 g long-grain rice, rinsed|400 g tinned chopped tomatoes|650 ml beef stock|1 tsp dried oregano|Salt and pepper',"Warm oil, soften onion and peppers for 6 minutes, then add mince and cook, breaking it up.","Add rinsed rice, tomatoes, stock and oregano. Bring to the boil, cover tightly and reduce the heat.",25,'Beef, rice and tomatoes cook together in one covered pot.',True,'Check the rice is tender, adding a little boiling water if needed. Season, rest covered for 5 minutes and serve immediately.')
pot('Lamb keema with peas','500 g lamb mince|1 onion, chopped|2 garlic cloves, chopped|1 tbsp grated ginger|1 tbsp oil|2 tsp garam masala|1 tsp cumin|400 g tinned chopped tomatoes|150 g frozen peas|150 ml water|250 g dry rice|Salt',"Warm oil and soften onion for 6 minutes. Add garlic, ginger and lamb mince. Cook, breaking up the mince.","Stir in cumin and garam masala, then tomatoes and water. Cook rice separately and add peas for the final 5 minutes of simmering.",25,'A home-style lamb mince curry with peas and rice.',True,'Check the peas are piping hot, season with salt and serve with the freshly cooked rice.')
pot('Paneer and pea curry','400 g paneer, cubed|1 onion, chopped|2 garlic cloves, chopped|1 tbsp oil|2 tsp garam masala|1 tsp turmeric|400 g tinned chopped tomatoes|200 g frozen peas|150 ml water|100 g plain yoghurt|250 g dry rice|Salt',"Warm oil and soften onion for 6 minutes. Add garlic and spices and stir for 1 minute.","Add tomatoes, water and paneer. Cook rice separately. Add peas for the final 5 minutes; take off the heat before stirring in the yoghurt.",20,'Paneer and peas in a simple tomato sauce for a meat-free family meal.',False,'Season with salt, check everything is piping hot and serve over freshly cooked rice.')
pot('Aubergine and chickpea tagine','2 aubergines, in 2 cm pieces|480 g drained tinned chickpeas|1 onion, chopped|2 tbsp olive oil|1 tsp cumin|1 tsp cinnamon|400 g tinned chopped tomatoes|200 ml vegetable stock|60 g dried apricots, chopped|200 g instant couscous|240 ml boiling vegetable stock|Salt',"Warm olive oil and soften onion for 6 minutes. Add aubergine and cook for 8 minutes, turning.","Stir in cumin and cinnamon, then tomatoes, 200 ml stock, chickpeas and apricots. Near the end, cover couscous with the separate 240 ml boiling stock and stand for 5 minutes, or follow its packet.",30,'Aubergine, chickpeas and apricots make a warm, softly spiced pot.',False,'Check aubergine is completely tender. Season and serve the hot tagine over fluffed couscous.')
pot('Black bean rice pan','480 g drained tinned black beans|250 g long-grain rice, rinsed|1 onion, chopped|1 pepper, diced|1 tbsp oil|400 g tinned chopped tomatoes|500 ml vegetable stock|1 tsp cumin|1 lime|Salt',"Warm oil and soften onion and pepper for 7 minutes. Add cumin and rice, stirring for 30 seconds.","Add tomatoes and stock. Bring to the boil, cover and simmer gently. Fold in drained beans after 15 minutes and keep cooking until piping hot.",25,'A simple covered rice pan with black beans and lime.',False,'Check rice is completely tender, adding boiling water if needed. Season, squeeze over lime and serve straight away.')
pot('Turkey and kidney bean chilli','500 g turkey mince|480 g drained tinned kidney beans|1 onion, chopped|1 pepper, diced|1 tbsp oil|400 g tinned chopped tomatoes|200 ml chicken stock|2 tsp cumin|1 tsp mild chilli powder|250 g dry rice|Salt',"Warm oil and soften onion and pepper for 6 minutes. Add turkey mince and cook, breaking it into small pieces.","Stir in spices, tomatoes, stock and drained tinned kidney beans. Cook rice separately while the chilli simmers.",25,'A lighter mince chilli with tinned kidney beans and rice.',True,'Season and serve the piping-hot chilli over freshly cooked rice. Use tinned kidney beans, not raw dried beans.')

def soup(title,ings,start,sim,minutes,desc):add(title,F,15,minutes,4,ings,[start,sim,f"Bring to the boil, reduce to a gentle simmer and cook for about {minutes} minutes, until the vegetables and pulses are completely tender.","Blend carefully with a stick blender for a smooth soup, or mash and leave chunky. If blending hot soup in a jug, follow the blender’s hot-liquid instructions and work in small batches.","Taste, adjust the listed seasonings and serve hot."],desc)
soup('Sweet potato and lentil soup','600 g sweet potatoes, peeled and diced|150 g dry red lentils, rinsed|1 onion, chopped|1 tbsp olive oil|1 tsp cumin|1 litre vegetable stock|1 tbsp lemon juice|Salt and pepper',"Warm oil and soften onion for 6 minutes. Stir in cumin for 30 seconds.","Add sweet potatoes, lentils and stock. Reserve the lemon juice to stir in at the end.",30,'Sweet potatoes and red lentils make a thick, warming soup.')
soup('Leek and potato soup','3 leeks, washed and sliced|600 g potatoes, peeled and diced|20 g butter|1 litre vegetable stock|100 ml milk|Salt and pepper',"Melt butter and soften leeks gently for 8 minutes without browning.","Add potatoes and stock. Stir the milk in after blending and reheat gently until piping hot.",25,'A gentle leek and potato soup for a simple family lunch.')

# Bakes and pies: cook filling and starches before finishing in the oven.
def bake(title,ings,prepsteps,minutes,desc,meat=False,tip=''):
 add(title,F,25,minutes,4,ings,["Heat the oven to 200°C (180°C fan). Lightly grease a suitable ovenproof dish using a little of the listed fat.",*prepsteps,f"Transfer to the dish and bake for about {minutes} minutes, until the top is golden and the centre is piping hot.",*([safe] if meat else []),"Rest for 5 minutes before serving."],desc,tip)
bake('Everyday cottage pie','500 g beef mince|1 onion, chopped|2 carrots, diced|1 tbsp oil|2 tbsp tomato purée|300 ml beef stock|1 tbsp Worcestershire sauce|800 g potatoes, peeled and diced|30 g butter|80 ml milk|Salt and pepper',["Boil potatoes until tender, about 15–20 minutes. Drain and mash with butter, milk and seasoning.","Warm oil and soften onion and carrots for 8 minutes. Add beef and cook, breaking it up. Stir in tomato purée, stock and Worcestershire sauce; simmer for 15 minutes and check mince is cooked through.","Spoon filling into the dish and spread mashed potato over it."],25,'A simple beef filling under a golden mashed potato top.',True)
bake('Easy family fish pie','600 g boneless mixed fish, thawed|800 g potatoes, peeled and diced|400 ml milk|30 g butter|30 g plain flour|100 g frozen peas|40 g cheddar, grated|Salt and pepper',["Boil potatoes until tender, drain and mash with 50 ml of the milk and half the butter. Season.","Melt remaining butter, stir in flour and cook for 1 minute. Gradually whisk in remaining milk. Simmer, stirring, for 3 minutes until smooth and thick.","Put fish and peas in the dish and pour over the sauce. Cover with mash and grated cheddar."],35,'Fish and peas under creamy mash, baked until hot right through.',True)
bake('Chicken and broccoli pasta bake','300 g pasta|400 g boneless chicken breast, diced|250 g broccoli, in florets|1 tbsp oil|300 ml milk|150 g cream cheese|80 g cheddar, grated|1 tsp mustard|Black pepper',["Cook pasta following the packet, adding broccoli for the last 5 minutes. Drain.","Warm oil in a pan and cook chicken pieces thoroughly. Check they reach 75°C for 30 seconds. Stir in milk, cream cheese and mustard; heat gently until smooth.","Combine chicken sauce, pasta and broccoli in the dish, season with pepper and cover with cheddar."],20,'A generous chicken and broccoli pasta bake with a simple cheese sauce.',True)
bake('Vegetable lasagne','9 dried lasagne sheets suitable for oven baking|1 onion, chopped|2 courgettes, diced|200 g mushrooms, chopped|1 tbsp olive oil|700 g passata|1 tsp dried oregano|500 ml milk|40 g butter|40 g plain flour|100 g vegetarian cheese, grated|Salt and pepper',["Warm oil and soften onion, courgettes and mushrooms for 10 minutes. Add passata, oregano and seasoning; simmer for 10 minutes.","Melt butter separately, stir in flour for 1 minute and gradually whisk in milk. Simmer, stirring, until smooth and thick.","Layer vegetable sauce, lasagne sheets and white sauce in the dish, finishing with sauce and cheese. Check the lasagne packet for any extra liquid or cooking time needed."],40,'Layers of vegetables, pasta and a simple white sauce.','Allow enough liquid for your chosen lasagne sheets and check the centre sheets are completely tender before serving.')
bake('Tomato and lentil pasta bake','300 g pasta|480 g drained tinned green lentils|1 onion, chopped|1 tbsp olive oil|600 g passata|1 tsp dried oregano|100 g spinach|100 g grated vegetarian cheese|Salt and pepper',["Cook pasta following the packet and drain.","Warm oil and soften onion for 6 minutes. Add passata, lentils and oregano; simmer for 10 minutes. Stir in spinach until wilted and season.","Combine pasta and sauce in the dish and scatter with cheese."],20,'Lentils and tomato sauce turn a pasta bake into a filling family dinner.')
bake('Spinach and feta puff pie','320 g ready-rolled puff pastry|300 g spinach|200 g feta, crumbled|1 onion, finely chopped|1 tbsp olive oil|2 eggs|1 tbsp milk|Black pepper',["Warm oil and soften onion for 6 minutes. Add spinach and wilt completely. Cool briefly, then press out excess liquid.","Mix spinach, onion, feta, one beaten egg and pepper. Put in a shallow pie dish and cover with pastry, trimming and crimping edges.","Beat remaining egg with milk. Brush over pastry and cut a small steam hole."],30,'Spinach and feta tucked beneath a crisp puff pastry lid.')
bake('Tuna and potato bake','600 g potatoes, peeled and thinly sliced|290 g drained tinned tuna|150 g frozen peas|300 ml milk|150 g cream cheese|80 g cheddar, grated|1 tsp mustard|Black pepper',["Boil the potato slices for 8–10 minutes until almost tender and drain carefully.","Warm milk, cream cheese and mustard in a saucepan, stirring until smooth. Add tuna, peas and pepper and heat until piping hot.","Layer potatoes and tuna sauce in the dish, finishing with potatoes and cheddar."],30,'Tinned tuna and potatoes in a creamy mustard sauce.')
bake('Roasted cauliflower cheese','1 large cauliflower, in florets|1 tbsp olive oil|400 ml milk|30 g butter|30 g flour|120 g cheddar, grated|1 tsp mustard|Black pepper',["Toss cauliflower with oil and roast on a tray for 20 minutes while you make the sauce.","Melt butter, stir in flour for 1 minute, then gradually whisk in milk. Simmer until thick. Stir in mustard and two-thirds of the cheese, then season with pepper.","Put roasted cauliflower in the dish, cover with sauce and remaining cheddar."],20,'Roasted cauliflower with a bubbling cheddar sauce.')
bake('Chicken and leek pie','500 g boneless chicken thigh, diced|2 leeks, washed and sliced|20 g butter|1 tbsp plain flour|250 ml chicken stock|100 ml single cream|320 g ready-rolled puff pastry|1 egg, beaten|Black pepper',["Melt butter and soften leeks for 6 minutes. Add chicken and cook for 8–10 minutes. Stir in flour, then stock and cream.","Simmer for 10 minutes and check chicken reaches 75°C for 30 seconds. Season with pepper, spoon into the dish and cool for 10 minutes.","Cover with pastry, crimp edges, brush with beaten egg and cut a steam hole."],30,'A simple chicken and leek filling beneath golden puff pastry.',True)
bake("Lentil shepherd's pie",'480 g drained tinned green lentils|1 onion, chopped|2 carrots, diced|1 tbsp olive oil|2 tbsp tomato purée|250 ml vegetable stock|100 g peas|800 g potatoes, peeled and diced|30 g butter|80 ml milk|Salt and pepper',["Boil potatoes until tender, drain and mash with butter, milk and seasoning.","Warm oil and soften onion and carrots for 8 minutes. Add tomato purée, lentils, stock and peas; simmer for 12 minutes until tender and piping hot.","Spoon the lentil filling into the dish and cover with mashed potato."],25,'A lentil and vegetable filling under a family-sized mashed potato top.')
bake('Meatball pasta bake','500 g beef mince|1 egg|40 g breadcrumbs|300 g pasta|600 g passata|1 onion, chopped|1 tbsp olive oil|1 tsp dried oregano|100 g mozzarella, grated|Salt and pepper',["Mix mince, egg, breadcrumbs and seasoning. Form 20 small meatballs. Warm oil and brown them in a wide pan, turning.","Add onion and soften for 5 minutes, then add passata and oregano. Cover and simmer gently for 20 minutes; check meatball centres reach 75°C for 30 seconds. Cook pasta separately and drain.","Combine pasta and meatball sauce in the dish and add mozzarella."],20,'Small beef meatballs and pasta beneath a melted mozzarella top.',True)
bake('White bean and mushroom pie','480 g drained tinned cannellini beans|300 g mushrooms, sliced|1 onion, chopped|20 g butter|1 tbsp plain flour|250 ml vegetable stock|100 ml single cream|320 g ready-rolled puff pastry|1 egg, beaten|Black pepper',["Melt butter and soften onion and mushrooms for 10 minutes. Stir in flour for 1 minute, then gradually add stock and cream.","Add beans and pepper and simmer for 5 minutes until thick and hot. Spoon into a pie dish and cool for 10 minutes.","Cover with pastry, crimp edges, brush with egg and cut a steam hole."],30,'White beans and mushrooms in a creamy pie filling.')

add('Stovetop macaroni cheese',F,10,20,4,'300 g macaroni|40 g butter|40 g plain flour|600 ml milk|150 g cheddar, grated|1 tsp mustard|Black pepper',["Cook macaroni following the packet and drain.","Melt butter in a saucepan. Stir in flour for 1 minute, then gradually whisk in milk. Simmer, stirring, until smooth and thick.","Take off the heat and stir in cheddar and mustard. Add pepper, then fold in the hot macaroni and reheat gently until piping hot."],'A familiar stovetop macaroni cheese with a proper white sauce.')
add('Turkey meatballs in tomato sauce',F,20,25,4,'500 g turkey mince|1 egg|40 g breadcrumbs|1 onion, finely chopped|1 tbsp oil|600 g passata|1 tsp oregano|250 g dry rice|Salt and pepper',["Mix turkey, egg, breadcrumbs and seasoning. Shape into 20 small meatballs.","Warm oil in a wide pan and brown meatballs, turning gently. Add onion and soften for 5 minutes.","Add passata and oregano. Cover and simmer for 20 minutes. Cook rice separately following the packet.",safe,"Serve the hot meatballs and sauce over freshly cooked rice."],'Turkey meatballs gently simmered in a simple tomato sauce.')
add('Sweet potatoes with smoky beans',F,10,60,4,'4 medium sweet potatoes|480 g drained tinned mixed beans|1 onion, chopped|1 tbsp olive oil|400 g tinned chopped tomatoes|1 tsp smoked paprika|80 g cheddar, grated|Salt and pepper',["Heat oven to 200°C (180°C fan). Scrub sweet potatoes, prick with a fork and bake for 45–60 minutes until completely soft.","Warm oil and soften onion for 6 minutes. Add paprika, tomatoes and beans and simmer for 15 minutes, adding water if needed. Season.","Split the baked sweet potatoes, fill with piping-hot beans and scatter with cheese."],'Soft baked sweet potatoes with smoky beans and cheddar.')
add('Beef and root vegetable stew',F,20,120,4,'600 g stewing beef, in 3 cm pieces|2 onions, chopped|3 carrots, sliced|2 parsnips, diced|600 g potatoes, diced|2 tbsp oil|2 tbsp plain flour|800 ml beef stock|2 tbsp tomato purée|1 tsp dried thyme|Salt and pepper',["Warm oil in a heavy casserole. Brown beef in batches and set aside. Soften onions for 6 minutes.","Stir in flour and tomato purée, then gradually add stock. Return beef and add thyme. Bring to the boil, cover and simmer gently for 75 minutes.","Add carrots, parsnips and potatoes and simmer for 40–45 minutes until beef and vegetables are completely tender. Add water if needed.",safe,"Season, rest for 5 minutes and serve hot."],'A slow, uncomplicated beef stew with plenty of root vegetables.')
add('Chicken and barley stew',F,20,50,4,'600 g boneless chicken thighs, diced|120 g pearl barley, rinsed|2 leeks, sliced|3 carrots, diced|1 tbsp olive oil|1 litre chicken stock|1 tsp dried thyme|100 g peas|Salt and pepper',["Warm oil and soften leeks and carrots for 7 minutes. Add chicken and cook for 5 minutes, stirring.","Add barley, stock and thyme. Bring to the boil, cover and simmer gently for 40–50 minutes, or until barley is completely tender.","Add peas for the final 5 minutes and check the stew is piping hot. "+safe,"Season and serve in warm bowls."],'Chicken and pearl barley make a warming one-pot family meal.')
add('Family tomato baked eggs',F,15,25,4,'8 eggs|1 onion, sliced|2 bell peppers, sliced|1 tbsp olive oil|800 g tinned chopped tomatoes|1 tsp cumin|1 tsp smoked paprika|4 slices bread|Salt and pepper',["Warm oil in a wide ovenproof pan. Soften onion and peppers for 10 minutes. Add cumin and paprika for 30 seconds.","Add tomatoes and season. Simmer for 10 minutes until thick. Heat oven to 200°C (180°C fan).","Make eight wells, crack in eggs and bake for 10–15 minutes until whites and yolks are fully set. Toast the bread and serve alongside."],'A family pan of eggs baked in a pepper and tomato sauce.')
add('Baked fish with tomatoes and beans',F,15,30,4,'4 boneless white fish fillets, about 150 g each|480 g drained tinned cannellini beans|400 g tinned chopped tomatoes|1 onion, finely chopped|1 tbsp olive oil|1 tsp dried oregano|1 lemon|Salt and pepper',["Heat oven to 200°C (180°C fan). Warm oil in an ovenproof pan and soften onion for 6 minutes.","Add tomatoes, beans and oregano. Simmer for 8 minutes and season lightly.","Lay fish on top, squeeze over half the lemon and bake for 15–20 minutes. "+safe,"Serve with remaining lemon wedges, dividing the beans between four plates."],'White fish baked over a warm bed of tomato and white beans.')
add('Broccoli and cheddar frittata',F,15,25,4,'8 eggs|250 g broccoli, in small florets|1 onion, sliced|100 g cheddar, grated|2 tbsp milk|1 tbsp olive oil|Salt and pepper',["Heat oven to 190°C (170°C fan). Boil broccoli for 5 minutes, drain and let steam dry.","Warm oil in an ovenproof non-stick frying pan and soften onion for 6 minutes. Add broccoli.","Beat eggs with milk, cheddar and seasoning. Pour into the pan, cook gently for 3 minutes, then transfer to the oven for 15–20 minutes until fully set in the centre.","Rest for 5 minutes and cut into wedges."],'A baked broccoli and cheddar frittata that slices neatly for the table.')
add('Roasted vegetable couscous',F,15,35,4,'2 courgettes, diced|2 bell peppers, diced|1 red onion, in wedges|300 g cherry tomatoes|2 tbsp olive oil|1 tsp cumin|250 g instant couscous|300 ml boiling vegetable stock|2 tbsp lemon juice|Salt and pepper',["Heat oven to 210°C (190°C fan). Toss vegetables with oil, cumin and seasoning on a large tray.","Roast for 30–35 minutes, turning once, until tender and lightly coloured.","Cover couscous with boiling stock and stand for 5 minutes, or follow its packet. Fluff with a fork, stir in lemon juice and combine with the hot roasted vegetables."],'A colourful roasted vegetable tray, folded through lemony couscous.')
add('Pork meatballs with noodles',F,20,25,4,'500 g pork mince|1 egg|40 g breadcrumbs|1 tbsp grated ginger|1 tbsp oil|250 g noodles|300 g stir-fry vegetables|2 tbsp soy sauce|1 tbsp honey|150 ml water',["Mix pork, egg, breadcrumbs and ginger. Shape into 20 small meatballs.","Warm oil in a wide pan and brown meatballs gently. Mix soy sauce, honey and water, pour in, cover and simmer for 15–20 minutes. "+safe,"Cook noodles following the packet. Steam or stir-fry the vegetables with a splash of water until tender and piping hot.","Serve noodles and vegetables with meatballs and their hot sauce."],'Small ginger pork meatballs with noodles and a simple soy sauce glaze.')
add('Lemon chicken and rice',F,15,35,4,'600 g boneless chicken thighs|250 g long-grain rice, rinsed|1 onion, chopped|1 tbsp olive oil|600 ml chicken stock|1 lemon, juice and zest|1 tsp dried oregano|150 g peas|Salt and pepper',["Warm oil in a wide lidded pan and brown chicken on both sides. Set aside and soften onion for 6 minutes.","Stir in rice, stock, lemon zest and oregano. Return chicken, bring to the boil, cover and simmer gently for 25–30 minutes.","Add peas for the final 5 minutes. Check rice is tender, adding water if needed. "+safe,"Stir in lemon juice, season, rest covered for 5 minutes and serve straight away."],'A covered pan of lemon chicken, rice and peas for an easy family dinner.')
assert len(recipes)==80,len(recipes)
D='Date night'
def date(title,ings,method,desc,prep=15,cook=25,tip=''):
 add(title,D,prep,cook,2,ings,method,desc,tip)
date('Lemon herb roast salmon','2 salmon fillets, about 150 g each|350 g small potatoes, halved|150 g green beans|1 lemon|1 tbsp olive oil|1 tbsp chopped dill|Salt and pepper',["Heat oven to 200°C (180°C fan). Boil potatoes for 10 minutes and drain. Toss with half the oil, season and roast for 15 minutes.","Add salmon, drizzle with remaining oil and half the lemon juice, then roast for 12–18 minutes. "+safe,"Steam green beans until tender, about 6 minutes. Serve with fish, potatoes, dill and remaining lemon wedges."],'Roast salmon, small potatoes and green beans for a relaxed dinner for two.',15,35)
date('Mushroom risotto for two','160 g risotto rice|250 g mushrooms, sliced|1 small onion, finely chopped|1 tbsp olive oil|20 g butter|650 ml hot vegetable stock|40 g vegetarian hard cheese, grated|1 tbsp parsley|Black pepper',["Keep the stock hot in a separate pan. Warm oil and half the butter in a wide saucepan. Soften onion for 6 minutes.","Add mushrooms and cook for 5 minutes. Stir in rice for 1 minute.","Add stock a ladle at a time, stirring and letting each addition absorb before adding more. Continue for 20–25 minutes until the rice is tender with a little bite and the risotto flows softly. Use extra boiling water if needed.","Take off the heat and stir in remaining butter, cheese, parsley and pepper. Rest for 2 minutes and serve."],'A patient pan of mushroom risotto, finished with cheese and parsley.',10,35)
date('Creamy garlic chicken','2 boneless chicken breasts|200 g mushrooms, sliced|2 garlic cloves, chopped|1 tbsp olive oil|100 ml chicken stock|100 ml single cream|1 tsp Dijon mustard|300 g potatoes, diced|Salt and pepper',["Boil potatoes until completely tender, about 15–20 minutes, then drain.","Warm oil in a frying pan. Brown chicken for 3 minutes per side. Add mushrooms and garlic and cook gently for 4 minutes.","Add stock, cream and mustard. Cover and simmer gently until chicken is thoroughly cooked. "+safe,"Season the sauce and serve with chicken and potatoes."],'Chicken and mushrooms in a simple cream and garlic pan sauce.')
date('Sea bass with tomatoes and olives','2 boneless sea bass fillets|250 g cherry tomatoes, halved|50 g pitted olives, sliced|1 garlic clove, chopped|1 tbsp olive oil|1 tbsp lemon juice|160 g dry couscous|190 ml boiling vegetable stock|Black pepper',["Heat oven to 200°C (180°C fan). Put tomatoes, olives, garlic and half the oil in a small baking dish and roast for 10 minutes.","Lay fish over the tomatoes and drizzle with remaining oil and lemon juice. Roast for a further 12–15 minutes. "+safe,"Cover couscous with boiling stock and stand for 5 minutes, or follow its packet. Fluff with a fork, season with pepper and serve with the fish and tomatoes."],'Sea bass baked over tomatoes and olives, served with fluffy couscous.')
date('Steak with peppercorn sauce','2 beef steaks, about 180 g each|350 g potatoes, cut into wedges|1 tbsp olive oil|1 tsp cracked black peppercorns|100 ml beef stock|80 ml single cream|1 tsp Dijon mustard|150 g green beans|Salt',["Heat oven to 220°C (200°C fan). Toss potato wedges with half the oil and a little salt; roast for 30–35 minutes until tender, turning halfway.","Warm remaining oil in a heavy frying pan. Cook steaks on both sides until thoroughly cooked. For this recipe, check the centre reaches 75°C for 30 seconds. Rest on a clean plate for 5 minutes.","Add stock, peppercorns, cream and mustard to the pan. Simmer gently for 3–4 minutes until slightly thickened. Steam beans until tender.","Serve steaks with wedges, green beans and the hot sauce."],'A straightforward steak supper with a creamy peppercorn pan sauce.',15,35,'Steak thickness changes the cooking time. This version uses a fully cooked steak; use a thermometer rather than judging by colour.')
date('Prawn and cherry tomato linguine','180 g linguine|200 g raw peeled prawns, thawed|250 g cherry tomatoes, halved|2 garlic cloves, chopped|1 tbsp olive oil|1 tbsp lemon juice|1 tbsp chopped parsley|Black pepper',["Cook linguine following its packet instructions, reserving a mug of cooking water.","Warm oil in a large frying pan. Soften garlic for 30 seconds, add tomatoes and cook for 7–8 minutes.","Add prawns and a splash of pasta water. Cook, stirring gently, until prawns are opaque and piping hot throughout. Check 75°C for 30 seconds with a clean thermometer.","Toss in pasta, lemon juice, parsley and pepper. Loosen with cooking water if needed and serve immediately."],'Linguine and prawns in a fresh cherry tomato and garlic sauce.',10,20)
date('Roasted aubergine with tahini','2 aubergines, halved lengthways|240 g drained tinned chickpeas|2 tbsp olive oil|1 tsp cumin|2 tbsp tahini|2 tbsp lemon juice|3 tbsp water|1 tbsp chopped parsley|Salt and pepper',["Heat oven to 210°C (190°C fan). Score the aubergine flesh, rub with half the oil, season and place cut-side up on a tray.","Roast for 35–45 minutes until completely soft. Toss chickpeas with remaining oil and cumin and add to the tray for the last 15 minutes, heating until piping hot.","Whisk tahini, lemon juice and water until smooth. Divide aubergines and chickpeas between plates, spoon over the dressing and finish with parsley."],'Soft roast aubergines with warm chickpeas and a lemon tahini dressing.',10,45)
date('Lemon ricotta ravioli','250 g ready-made ricotta ravioli|25 g butter|1 lemon, zest and 1 tbsp juice|80 g baby spinach|20 g vegetarian hard cheese, grated|Black pepper',["Cook ravioli following the packet instructions. Reserve a mug of cooking water.","Melt butter gently in a wide pan. Add lemon zest, spinach and 2 tbsp cooking water. Stir until spinach wilts.","Fold in the cooked ravioli, lemon juice, cheese and pepper. Add a little more cooking water if needed and serve immediately."],'Ready-made ricotta ravioli with a gentle lemon butter and spinach sauce.',10,10)
date('Pork medallions with apples','350 g pork tenderloin, cut into thick medallions|2 apples, cored and sliced|1 small onion, sliced|1 tbsp olive oil|150 ml chicken stock|1 tsp Dijon mustard|80 ml single cream|300 g potatoes, diced|Salt and pepper',["Boil potatoes until tender and drain. Warm oil in a frying pan and brown pork medallions on each side.","Add onion and apples and cook gently for 5 minutes. Stir in stock and mustard, cover and simmer until pork is cooked through. "+safe,"Stir in cream and heat gently without boiling hard. Season and serve the pork, apples and sauce with potatoes."],'Pork tenderloin with apple, mustard and a light cream sauce.')
date('Honey and soy glazed tofu','300 g firm tofu, drained and cubed|150 g dry rice|200 g broccoli, in florets|1 tbsp oil|2 tbsp soy sauce|1 tbsp honey|1 tbsp rice vinegar|1 tsp grated ginger|50 ml water',["Cook rice following the packet. Steam broccoli until tender and keep hot.","Warm oil in a non-stick pan. Cook tofu for 8–10 minutes, turning gently, following its packet cooking instructions.","Mix soy sauce, honey, vinegar, ginger and water. Add to tofu and simmer for 3–4 minutes until the glaze coats it and everything is piping hot.","Divide rice and broccoli between bowls and add glazed tofu."],'Golden tofu with a sweet and savoury glaze, rice and broccoli.',10,25)
date('Miso roast cod','2 boneless cod fillets, about 150 g each|1 tbsp white miso|1 tsp honey|1 tbsp rice vinegar|1 tsp sesame oil|150 g dry rice|200 g pak choi, halved',["Heat oven to 200°C (180°C fan). Mix miso, honey, vinegar and sesame oil. Spread over cod in a lined baking dish.","Roast for 15–20 minutes, depending on thickness. "+safe,"Cook rice following the packet and steam pak choi until tender, about 5–7 minutes. Serve with the hot cod and any pan juices."],'Miso-glazed cod with rice and simply steamed pak choi.',10,25)
date('Chickpea and saffron rice','160 g basmati rice, rinsed|240 g drained tinned chickpeas|1 small onion, chopped|1 tbsp olive oil|A small pinch saffron|400 ml hot vegetable stock|100 g frozen peas|1 tbsp lemon juice|1 tbsp chopped parsley|Black pepper',["Steep saffron in the hot stock for 5 minutes. Warm oil in a lidded saucepan and soften onion for 6 minutes.","Add rice, chickpeas and saffron stock. Bring to the boil, cover and simmer gently for 12 minutes or according to the rice packet, adding peas for the final 5 minutes.","Check rice is tender and everything is piping hot, adding boiling water and cooking longer if needed. Rest covered for 5 minutes.","Fluff with a fork and stir in lemon juice, parsley and black pepper. Serve immediately."],'Golden saffron rice with chickpeas, peas and lemon.',10,25)
date('Sweet potato coconut curry','400 g sweet potato, peeled and diced|240 g drained tinned chickpeas|1 small onion, chopped|1 tbsp oil|1 tbsp mild curry paste|200 ml coconut milk|200 ml water|80 g spinach|150 g dry rice|1 tbsp lime juice',["Warm oil and soften onion for 6 minutes. Stir in curry paste for 1 minute.","Add sweet potato, chickpeas, coconut milk and water. Simmer gently for 20–25 minutes until sweet potato is completely tender.","Cook rice following the packet. Add spinach to the curry and heat until wilted and piping hot. Finish with lime juice.","Serve the curry over freshly cooked rice."],'Sweet potato and chickpeas in a gently spiced coconut curry.')
date('Lemon caper chicken','2 boneless chicken breasts, butterflied|1 tbsp plain flour|1 tbsp olive oil|15 g butter|150 ml chicken stock|1 tbsp lemon juice|1 tbsp drained capers|1 tbsp chopped parsley|150 g dry rice|Black pepper',["Cook rice following the packet. Dust the chicken lightly with flour and pepper.","Warm oil and butter in a frying pan. Cook chicken on both sides until golden. Add stock, lemon juice and capers.","Simmer gently until chicken is fully cooked. "+safe,"Stir parsley into the sauce and serve with chicken and freshly cooked rice."],'Butterflied chicken with a lemon and caper pan sauce.')
date('Salmon with creamy spinach','2 salmon fillets, about 150 g each|200 g spinach|1 garlic clove, chopped|1 tbsp olive oil|100 ml single cream|1 tsp Dijon mustard|300 g small potatoes, halved|1 tbsp lemon juice|Black pepper',["Boil potatoes until tender, about 15–20 minutes. Drain and keep hot.","Warm half the oil in a frying pan. Cook salmon gently on both sides until thoroughly cooked. "+safe,"In a separate pan, warm remaining oil and soften garlic for 30 seconds. Wilt spinach, then stir in cream and mustard. Heat gently until piping hot.","Add lemon juice and pepper and serve the salmon with creamy spinach and potatoes."],'Salmon, potatoes and a quick creamy spinach sauce for two.')
date("Squash and goat's cheese tart",'200 g ready-rolled puff pastry|300 g butternut squash, in small cubes|1 tbsp olive oil|1 small red onion, sliced|80 g soft goat cheese|1 tsp dried thyme|1 egg, beaten|Black pepper',["Heat oven to 210°C (190°C fan). Toss squash and onion with oil, thyme and pepper and roast for 20 minutes until just tender.","Lay pastry on baking paper and score a 1 cm border without cutting through. Prick the centre and brush the border with egg.","Arrange vegetables inside the border and crumble goat cheese over them. Bake for 20–25 minutes until pastry is puffed and cooked on the base.","Rest for 5 minutes and cut into two portions."],'Roast squash and goat cheese on a crisp puff pastry base.',15,45)
date('Duck breast with orange sauce','2 duck breasts, about 180 g each|2 oranges, juice and zest|100 ml chicken stock|1 tsp honey|1 tsp cornflour|1 tbsp cold water|300 g potatoes, diced|150 g green beans|Salt and pepper',["Boil potatoes until tender and steam green beans. Keep hot. Pat duck dry, score the skin without cutting into the flesh and season.","Put duck skin-side down in a cold heavy pan. Heat gradually and cook for 8–10 minutes to render the fat, then turn and cook until thoroughly cooked. Check the thickest part reaches 75°C for 30 seconds; finish in a 180°C oven if needed. Rest on a clean plate for 5 minutes.","Pour most of the fat from the pan into a heatproof container. Add orange juice, zest, stock and honey and simmer for 4 minutes. Mix cornflour and cold water, stir in and simmer until lightly thickened.","Slice the cooked duck and serve with potatoes, beans and orange sauce."],'Duck breast with a simple orange sauce and green vegetables.',15,35,'This version uses duck cooked through for food safety. Check the centre with a clean thermometer.')
date('Individual mushroom Wellingtons','250 g mushrooms, finely chopped|1 small onion, finely chopped|1 tbsp olive oil|1 garlic clove, chopped|1 tsp dried thyme|40 g breadcrumbs|80 g cream cheese|250 g ready-rolled puff pastry|1 egg, beaten|Black pepper',["Heat oil in a wide pan. Soften onion for 5 minutes, add mushrooms, garlic and thyme and cook for 10–12 minutes until their moisture evaporates. Cool for 10 minutes.","Stir in breadcrumbs, cream cheese and pepper. Heat oven to 200°C (180°C fan).","Cut pastry into two large rectangles. Put filling in the centre of each, brush edges with egg and fold to seal completely. Place seam-side down on baking paper and brush tops with egg.","Bake for 25–30 minutes until pastry is golden and cooked on the base and filling is piping hot. Rest for 5 minutes before serving."],'Two small mushroom parcels with a crisp pastry shell.',25,30)
date('Beetroot and feta orzo','160 g orzo|200 g ready-cooked beetroot, diced|100 g feta, crumbled|60 g spinach|1 tbsp olive oil|1 tbsp lemon juice|1 tbsp chopped dill|Black pepper',["Cook orzo following the packet, reserving a mug of cooking water.","Warm oil in a saucepan and add beetroot with 2 tbsp water. Heat until piping hot, then add spinach and wilt.","Fold in orzo, lemon juice and half the feta. Loosen with cooking water if needed.","Divide between bowls and finish with remaining feta, dill and pepper."],'Beetroot colours a simple orzo dish, finished with feta and dill.',10,20)
date('Chocolate pots for two','80 g dark chocolate, chopped|100 ml double cream|1 tsp caster sugar|1 tsp vanilla extract|60 g raspberries',["Put chopped chocolate in a heatproof bowl. Heat cream and sugar in a small pan until steaming, without boiling hard.","Pour cream over the chocolate and stand for 2 minutes. Stir gently until smooth, then add vanilla.","Divide between two small heatproof glasses or ramekins. Cool briefly, cover and refrigerate for at least 2 hours until set.","Add raspberries just before serving. Keep chilled until required."],'Small chocolate cream pots that can be prepared before dinner.',10,5,'Allow at least 2 hours of chilling in addition to the active preparation time. Contains milk; check chocolate labels for allergens.')
assert len(recipes)==100,len(recipes)
Path('lib/at-home-recipes.json').write_text(json.dumps(recipes,ensure_ascii=False,indent=2)+'\n')
print('Wrote',len(recipes),'recipes:',{g:sum(r['atHomeCategory']==g for r in recipes) for g in [Q,F,D]})
